head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/etn_recv_common.js");
scwin.vScrenID = "ULDSTF08001.xml"; //화면ID
scwin.fr_SecuGrpId = SECUGRP_ID_EN;
scwin.readOnlyYn = "N";
scwin.procJob = "";
scwin.logicPackYn = "Y";
scwin.clickBzProcsNo = ""; //업무처리번호 (클릭된)
scwin.clickListBzTpCd = ""; //상장업무구분코드 (그리드 로우 클릭시 상장업무구분코드를 획득함)
scwin.clickIsuCd = ""; //종목코드(클릭된)
scwin.clickAddIsuRnd = ""; //추가상장차수(클릭된)
scwin.clickListEtpProdTpCd = ""; // ETP상품구분코드(클릭된)
scwin.vListInit = true;
scwin.logicPackYn = "Y";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명 : fn_set_code()
 * 설명    : 발행회사 콤보박스 조회
 **********************************************/
scwin.fn_set_code = function() {
    dts_EtnInst.DataID = "/CodeAction.do?method=listWrntCd&For=R";
    dts_EtnInst.Reset();
};


//필요한 경우 넣으면 됨(신청구분 선택하기 위한 폼체크이나 불필요함
scwin.fn_CheckSearchForm = function() {
    var bCheckForm = true;
    if ($c.stf.getObjectValue(cmb_ISUR_CD) == "") {
        bCheckForm = false;
    }
    return bCheckForm;
};


/********************************************** 
 * 함수명 : fn_list_sync()
 * 설명    :  상장신청접수 에 대한 목록 조회
 **********************************************/
scwin.fn_list_sync = function() {
    //if (!fn_CheckSearchForm()) { alert("신청구분을 선택하셔야 합니다!"); return; }

    var v_listBzTpCd = ""; //심사청구,상장신청 구분코드
    scwin.vListInit = false; //처음 화면 로딩시 두 번 리스트 조회 안타게 하기 위함.

    //신규상장접수
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        if ($c.stf.getObjectValue(cmb_LIST_BZ_TP_CD) == "1") {
            v_listBzTpCd = "701"; //예비심사청구

        } else if ($c.stf.getObjectValue(cmb_LIST_BZ_TP_CD) == "2") {
            v_listBzTpCd = "702"; //신규상장신청

        }
        var url = "/etn/EtnListedRcv.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listEtnReceiptRcv";
        url += "&inputMessageId=ETN_LISTEDRCV_SEARCH_OUT";
        url += "&ISUR_CD=" + $c.stf.getObjectValue(cmb_ISUR_CD);
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.Reset();
        $c.cm.ShowWin(grd_List_1);

        //추가상장접수

    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        if ($c.stf.getObjectValue(cmb_LIST_BZ_TP_CD) == "1") {
            v_listBzTpCd = "703"; //추가상장예비심사청구

        } else if ($c.stf.getObjectValue(cmb_LIST_BZ_TP_CD) == "2") {
            v_listBzTpCd = "704"; //추가상장신청

        }
        var url = "/etn/EtnListedRcv.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listEtnAddReceiptRcv";
        url += "&inputMessageId=ETN_LISTEDRCV_SEARCH_OUT";
        url += "&ISUR_CD=" + $c.stf.getObjectValue(cmb_ISUR_CD);
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        // 신규상장접수(손실제한)
        if ($c.stf.getObjectValue(cmb_LIST_BZ_TP_CD) == "1") {
            v_listBzTpCd = "701"; //예비심사청구

        } else if ($c.stf.getObjectValue(cmb_LIST_BZ_TP_CD) == "2") {
            v_listBzTpCd = "702"; //신규상장신청

        }
        v_etpProdTpCd = "4";
        var url = "/etn/EtnListedRcv.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listEtnLossLmtReceiptRcv";
        url += "&inputMessageId=ETN_LISTEDRCV_LOSSLMT_SEARCH_OUT";
        url += "&ISUR_CD=" + $c.stf.getObjectValue(cmb_ISUR_CD);
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        dts_List_3.DataID = encodeURI(url);
        dts_List_3.Reset();
        $c.cm.ShowWin(grd_List_3);
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        // 추가상장접수(손실제한)
        if ($c.stf.getObjectValue(cmb_LIST_BZ_TP_CD) == "1") {
            v_listBzTpCd = "703"; //추가상장예비심사청구

        } else if ($c.stf.getObjectValue(cmb_LIST_BZ_TP_CD) == "2") {
            v_listBzTpCd = "704"; //추가상장신청

        }
        var url = "/etn/EtnListedRcv.do";
        url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=listEtnLossLmtAddReceiptRcv";
        url += "&inputMessageId=ETN_LISTEDRCV_LOSSLMT_SEARCH_OUT";
        url += "&ISUR_CD=" + $c.stf.getObjectValue(cmb_ISUR_CD);
        url += "&LIST_BZ_TP_CD=" + v_listBzTpCd;
        dts_List_4.DataID = encodeURI(url);
        dts_List_4.Reset();
        $c.cm.ShowWin(grd_List_4);
    }
};



/********************************************** 
 * 함수명 : fn_setBzProcsNo()
 * 설명    : (신규접수)클릭된 그리드에 대한 업무처리번호 획득
 **********************************************/
scwin.fn_setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(eval(obj), "BZ_PROCS_NO");
    scwin.clickListBzTpCd = dtsObj.getCellData(eval(obj), "LIST_BZ_TP_CD");
    scwin.clickListEtpProdTpCd = dtsObj.getCellData(eval(obj), "ETP_PROD_TP_CD");

    //추가상장인 경우
    if (MaxTab_01.getSelectedTabIndex() == 2 || MaxTab_01.getSelectedTabIndex() == 4) {
        scwin.clickIsuCd = dtsObj.getCellData(eval(obj), "ISU_CD");
        scwin.clickAddIsuRnd = dtsObj.getCellData(eval(obj), "ADD_ISU_RND");
    }
};



/********************************************** 
 * 함수명 : fn_OpenNewWin()
 * 설명    :  상장신청접수 에 대한 상세 팝업조회
 **********************************************/
scwin.fn_OpenNewWin = function(row, dtsObj) {
    if (row > 0) {
        //그리드에서 선택시
        //획득 업무처리번호, 상장업무구분코드
        scwin.fn_setBzProcsNo(row, dtsObj);
        $c.etrc.fn_OpenDetailRecv(scwin.clickListBzTpCd, scwin.clickListEtpProdTpCd);
    }
};



/********************************************** 
 * 함수명 : fn_ExcelDown()
 * 설명    : 정보를 excel로 다운 받는다.
 **********************************************/
scwin.fn_ExcelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "신규상장접수(일반)목록", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_List_2, "추가상장접수(일반)목록", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        $c.data.downloadGridViewExcel(grd_List_3, "신규상장접수(손실제한)목록", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        $c.data.downloadGridViewExcel(grd_List_4, "추가상장접수(손실제한)목록", "", "8");
    }
};



/********************************************** 
 * 함수명 : fn_packacpt()
 * 설명    : 접수 처리
 **********************************************/
scwin.fn_packacpt = function() {
    var dtsObj = scwin.fn_getDataSet();
    var vSelectCnt = scwin.fn_selectIsuCheckCnt(dtsObj);
    if (vSelectCnt == 0) {
        $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    if (!$c.etrc.fn_CheckForm("1")) {
        return;
    }

    //procJob = ' 선택한 '+vSelectCnt+'종목에 대한 접수처리 ';
    scwin.procJob = ' 선택한 종목에 대한 일괄접수처리 ';
    var res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.procJob));
    if (res) {
        //선택한 종목에 대하여 '접수' 상태 변경
        for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
            if (dtsObj.getCellData(i, "CHECK") == "T") {
                dtsObj.setCellData(i, "LIST_PROCS_STAT_CD", ETN_RECV_PROC_CD_10);
            }
        }
        trs_Save.Action = $c.lce.fn_encodeNSession("/etn/EtnListedRcv.do?method=receiveEtnAcptRet&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03);
        trs_Save.KeyName = "toinb_dataid4";
        if (MaxTab_01.getSelectedTabIndex() == 1) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_1)";
        } else if (MaxTab_01.getSelectedTabIndex() == 2) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_2)";
        } else if (MaxTab_01.getSelectedTabIndex() == 3) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_3)";
        } else if (MaxTab_01.getSelectedTabIndex() == 4) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_4)";
        }
        trs_Save.Post();
    }
};



/********************************************** 
 * 함수명 : fn_packret()
 * 설명    : 반송 처리
 **********************************************/
scwin.fn_packret = function() {
    var dtsObj = scwin.fn_getDataSet();
    var vSelectCnt = scwin.fn_selectIsuCheckCnt(dtsObj);
    if (vSelectCnt == 0) {
        $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    if (!$c.etrc.fn_CheckForm("2")) {
        return;
    }

    //procJob = ' 선택한 '+vSelectCnt+'종목에 대한 반송처리 ';
    scwin.procJob = ' 선택한 종목에 대한 일괄반송처리 ';
    var res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.procJob));
    if (res) {
        //선택한 종목에 대하여 '반송' 상태 변경
        for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
            if (dtsObj.getCellData(i, "CHECK") == "T") {
                dtsObj.setCellData(i, "LIST_PROCS_STAT_CD", ETN_RECV_PROC_CD_02);
                dtsObj.setCellData(i, "RET_RSN_CD", $c.stf.getObjectValue(cmb_RETN_BZ_TP_CD));
                dtsObj.setCellData(i, "RET_RSN", $c.stf.getObjectValue(cmb_RETN_BZ_TP_CD) + ":" + $c.stf.getObjectValue(txb_RET_RSN));
            }
        }
        trs_Save.Action = $c.lce.fn_encodeNSession("/etn/EtnListedRcv.do?method=receiveEtnAcptRet&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03);
        trs_Save.KeyName = "toinb_dataid4";
        if (MaxTab_01.getSelectedTabIndex() == 1) {
            //신규상장접수(일반)
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_1)";
        } else if (MaxTab_01.getSelectedTabIndex() == 2) {
            //추가상장접수
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_2)";
        } else if (MaxTab_01.getSelectedTabIndex() == 3) {
            //신규상장접수(손실제한)
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_3)";
        } else if (MaxTab_01.getSelectedTabIndex() == 4) {
            //추가상장접수(손실제한)
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_4)";
        }
        trs_Save.Post();
        $c.stf.setObjectValue(txb_RET_RSN, ""); //초기화

    }
};



/********************************************** 
 * 함수명 : fn_getDataSet()
 * 설명    : Tab에 따른 Dataset 가져오기
 **********************************************/
scwin.fn_getDataSet = function() {
    var dtsObj;
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        dtsObj = dts_List_1;
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        dtsObj = dts_List_2;
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        dtsObj = dts_List_3;
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        dtsObj = dts_List_4;
    }
    return dtsObj;
};


/********************************************** 
 * 함수명 : fn_getDataSet()
 * 설명    : Tab에 따른 Dataset 가져오기
 **********************************************/
scwin.fn_selectIsuCheckCnt = function(dtsObj) {
    var k = 0;
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        if (dtsObj.getCellData(i, "CHECK") == "T") {
            k++;
        }
    }
    return k;
};
scwin.btn_RcvPrc_onclick = function() {
    /*if ( js_svrGubun == 'dr') {
    		alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
    		return;
    }*/
    scwin.fn_packacpt();
};
scwin.btn_RetPrc_onclick = function() {
    if (MaxTab_01.getSelectedTabIndex() == "1" || MaxTab_01.getSelectedTabIndex() == "2") {
        if ($c.stf.getObjectValue(cmb_RETN_BZ_TP_CD) == "02") {
            $c.win.alert("해당사유는 손실제한 ETN일때만 선택가능합니다.");
            cmb_RETN_BZ_TP_CD.focus();
            return;
        }
    }
    scwin.fn_packret();
};
scwin.cmb_ISUR_CD_OnSelChange = function() {
    //발행회사 조회시 초기에 재조회 안타게 하기 위함
    if (scwin.vListInit == false) {
        scwin.fn_list_sync();
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Excel_onclick = function() {
    //Download excel data
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
scwin.grd_List_1_OnHeadCheckClick = function(col, colid, bCheck) {
    //신규상장접수 > 헤드체크박스 클릭
    $c.lce.fn_setCheckBox(grd_List_1, dts_List_1, bCheck);
};
scwin.grd_List_1_OnDblClick = function(row, colid) {
    //신규상장접수 > Grid Row Click
    if (colid == 'ISU_ABBRV') {
        scwin.fn_OpenNewWin(row, dts_List_1);
    }
};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_1_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_1);
};
scwin.grd_List_2_OnHeadCheckClick = function(col, colid, bCheck) {
    //추가상장접수 > 헤드체크박스 클릭
    $c.lce.fn_setCheckBox(grd_List_2, dts_List_2, bCheck);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.grd_List_2_OnDblClick = function(row, colid) {
    //추가상장접수 > Grid Row Click
    if (colid == 'ISU_ABBRV') {
        scwin.fn_OpenNewWin(row, dts_List_2);
    }
};
scwin.grd_List_3_OnDblClick = function(row, colid) {
    //신규상장접수 > Grid Row Click
    if (colid == 'ISU_ABBRV') {
        scwin.fn_OpenNewWin(row, dts_List_3);
    }
};
scwin.dts_List_3_OnLoadError = function() {
    $c.stf.alert_error(dts_List_3);
};
scwin.dts_List_3_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_3);
};
scwin.grd_List_4_OnDblClick = function(row, colid) {
    //신규상장접수 > Grid Row Click
    if (colid == 'ISU_ABBRV') {
        scwin.fn_OpenNewWin(row, dts_List_4);
    }
};
scwin.dts_List_4_OnLoadError = function() {
    $c.stf.alert_error(dts_List_4);
};
scwin.dts_List_4_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_4);
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
    scwin.fn_list_sync();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    if (nIndex == "3") {
        // 신규상장접수(손실제한)		
        $c.stf.showObj(btn_LgcChk, true);
    } else {
        $c.stf.showObj(btn_LgcChk, false);
    }
    scwin.fn_list_sync();
};
scwin.gform_onload = function() {
    scwin.fn_set_code(); //발행기관
    $c.etrc.fn_SetRetTypeCombo(dts_RetTp); //심사반송구분코드
    MaxTab_01.setSelectedTabIndex(1);
    $c.cm.PanelToGroupBox(panel_Top);
    $c.stf.showObj(btn_LgcChk, false);
};
scwin.cmb_LIST_BZ_TP_CD_OnSelChange = function() {
    scwin.fn_list_sync();
};
scwin.btn_LgcChk_onclick = function() {
    var dtsObj = scwin.fn_getDataSet();
    if (scwin.fn_selectIsuCheckCnt(dtsObj) == 0) {
        $c.win.alert("[종목]을 선택하세요.");
        return;
    } else {
        $c.etrc.fn_OpenLogicCheck();
    }
};
scwin.grd_List_1_OnHeadCheckClick = function(col, colid, bCheck) {
    $c.lce.fn_setCheckBox(grd_List_1, dts_List_1, bCheck);
};
scwin.grd_List_2_OnHeadCheckClick = function(col, colid, bCheck) {
    $c.lce.fn_setCheckBox(grd_List_2, dts_List_2, bCheck);
};
scwin.grd_List_3_OnHeadCheckClick = function(col, colid, bCheck) {
